// Self-hosted brand assets for the v3 Finance design: the Timothy Finance mark (96px) and app
// icon (180px), cropped from the September 2026 Finance logo; Hero Regular and Bold, the brand
// typeface (Fontfabric free-font EULA, which permits @font-face use; the original fonts converted
// to WOFF2, not subset or edited); and the Outfit and Figtree variable fonts (latin subset, SIL
// Open Font License). They are served from this Worker's own origin so the page CSP can stay
// same-origin only -- no third-party font or image requests, and no referrer leaks.
// Generated file: regenerate from the source files rather than editing the base64 by hand.

export const BRAND_ASSETS = Object.freeze({
  '/assets/finance-mark.png': Object.freeze({ contentType: 'image/png', base64: '' }),
  '/assets/finance-icon.png': Object.freeze({ contentType: 'image/png', base64: '' }),
  '/assets/fonts/hero-regular.woff2': Object.freeze({ contentType: 'font/woff2', base64: '' }),
  '/assets/fonts/hero-bold.woff2': Object.freeze({ contentType: 'font/woff2', base64: '' }),
  '/assets/fonts/outfit.woff2': Object.freeze({ contentType: 'font/woff2', base64: '' }),
  '/assets/fonts/figtree.woff2': Object.freeze({ contentType: 'font/woff2', base64: '' }),
  '/apple-touch-icon.png': Object.freeze({ contentType: 'image/png', base64: '' }),
  '/apple-touch-icon-precomposed.png': Object.freeze({ contentType: 'image/png', base64: '' }),
  '/assets/finance-icon-192.png': Object.freeze({ contentType: 'image/png', base64: '' }),
  '/assets/finance-icon-512.png': Object.freeze({ contentType: 'image/png', base64: '' }),
  '/assets/finance-icon-maskable-512.png': Object.freeze({ contentType: 'image/png', base64: '' }),
  '/manifest.webmanifest': Object.freeze({ contentType: 'application/manifest+json', base64: '' }),
});

export function brandAssetBytes(asset) {
  const binary = atob(asset.base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
  return bytes;
}
